(()=>{var l=document.getElementById("loginForm");l.addEventListener("submit",e=>{e.preventDefault();let t=l.querySelectorAll("#loginForm input"),n={};t.forEach(o=>{let s=o.getAttribute("name"),i=o.value;n[s]=i}),c(n)});function c(e){let t=JSON.stringify(e);fetch("/login",{body:t,method:"POST",headers:{"Content-Type":"application/json"}}).then(n=>{n.ok?location.reload():console.error(n)})}function a(){let e=document.getElementById("messageDiv");fetch("/getmessages",{method:"GET"}).then(t=>t.json()).then(t=>{if(e.childNodes.forEach(o=>{e.removeChild(o)}),t.messages.length<1){e.classList.add("hidden");return}let n=document.createElement("ul");t.messages.forEach(o=>{let s=document.createElement("li");s.innerText=o,n.appendChild(s)}),e.appendChild(n),e.classList.remove("hidden")})}window.onload=()=>{a()};})();
